(484, 47, 5, 'Mix until smooth.', ''),
(485, 47, 6, 'Strain the batter to remove lumps.', ''),
(486, 47, 7, 'Grease kutsinta molds lightly.', ''),
(487, 47, 8, 'Pour batter into each mold.', ''),
(488, 47, 9, 'Steam for 25–30 minutes or until firm and translucent.', ''),
(489, 47, 10, 'Allow to cool completely.', ''),
(490, 47, 11, 'Remove from molds.', ''),
(491, 47, 12, 'Serve with grated coconut.', ''),
(492, 48, 1, 'Combine coconut milk, evaporated milk, condensed milk, and sugar in a saucepan.', ''),
(493, 48, 2, 'Heat over medium heat while stirring.', ''),
(494, 48, 3, 'Add corn kernels and continue stirring.', ''),
(495, 48, 4, 'Dissolve cornstarch in 1 cup of water.', ''),
(496, 48, 5, 'Slowly pour the cornstarch mixture into the saucepan.', ''),
(497, 48, 6, 'Stir continuously until the mixture becomes thick.', ''),
(498, 48, 7, 'Cook for another 5 minutes.', ''),
(499, 48, 8, 'Transfer to a greased rectangular dish.', ''),
(500, 48, 9, 'Spread evenly and sprinkle grated cheese on top.', ''),
(501, 48, 10, 'Allow to cool.', ''),
(502, 48, 11, 'Refrigerate for at least 2 hours before slicing.', ''),
(503, 48, 12, 'Add latik if desired and serve chilled.', ''),
(504, 49, 1, 'Prepare two tall serving glasses.', ''),
(505, 49, 2, 'Divide the sweetened banana, jackfruit, red beans, nata de coco, kaong, macapuno, and gulaman between the glasses.', ''),
(506, 49, 3, 'Add shaved ice until each glass is nearly full.', ''),
(507, 49, 4, 'Pour evaporated milk over the ice.', ''),
(508, 49, 5, 'Add leche flan and ube halaya.', ''),
(509, 49, 6, 'Place one scoop of ube ice cream on top of each serving.', ''),
(510, 49, 7, 'Sprinkle with pinipig.', ''),
(511, 49, 8, 'Serve immediately.', ''),
(512, 50, 1, 'Place sugar and water in a saucepan.', ''),
(513, 50, 2, 'Heat until the sugar becomes golden caramel.', ''),
(514, 50, 3, 'Carefully divide the caramel among 2–3 llaneras.', ''),
(515, 50, 4, 'Allow the caramel to harden.', ''),
(516, 50, 5, 'In a bowl, gently mix egg yolks, condensed milk, evaporated milk, and vanilla.', ''),
(517, 50, 6, 'Strain the mixture twice to remove bubbles and lumps.', ''),
(518, 50, 7, 'Pour the mixture into the prepared llaneras.', ''),
(519, 50, 8, 'Cover each llanera with foil.', ''),
(520, 50, 9, 'Arrange in a steamer.', ''),
(521, 50, 10, 'Steam over low heat for 35–45 minutes or until set.', ''),
(522, 50, 11, 'Cool completely.', ''),
(523, 50, 12, 'Refrigerate for at least 4 hours.', ''),
(524, 50, 13, 'Run a knife around the edges and invert onto a serving plate.', ''),
(525, 51, 1, 'If using fresh ube, boil until tender, peel, and grate.', ''),
(526, 51, 2, 'Combine coconut milk, condensed milk, evaporated milk, and sugar in a pan.', ''),
(527, 51, 3, 'Add grated ube and salt.', ''),
(528, 51, 4, 'Cook over low to medium heat while stirring continuously.', ''),
(529, 51, 5, 'Add butter and ube flavoring.', ''),
(530, 51, 6, 'Continue stirring for 30–40 minutes until thick and smooth.', ''),
(531, 51, 7, 'Transfer to a greased container.', ''),
(532, 51, 8, 'Allow to cool before serving or refrigerating.', ''),
(533, 52, 1, 'Peel the saba bananas and slice them lengthwise.', ''),
(534, 52, 2, 'Place one banana slice and a few pieces of jackfruit on each wrapper.', ''),
(535, 52, 3, 'Sprinkle approximately 1 teaspoon of brown sugar over the filling.', ''),
(536, 52, 4, 'Fold the sides inward and roll tightly.', ''),
(537, 52, 5, 'Seal the wrapper with water.', ''),
(538, 52, 6, 'Repeat with the remaining ingredients.', ''),
(539, 52, 7, 'Fry the turon until golden brown and crisp.', ''),
(540, 52, 8, 'Drain excess oil.', ''),
(541, 52, 9, 'Allow to cool slightly before serving.', ''),
(542, 53, 1, 'Combine gulaman powder, water, and sugar in a saucepan.', ''),
(543, 53, 2, 'Bring to a boil while stirring until the powder dissolves.', ''),
(544, 53, 3, 'Pour into a container and allow to set.', ''),
(545, 53, 4, 'Cut the gulaman into small cubes.', ''),
(546, 53, 5, 'In a large bowl, combine condensed milk and all-purpose cream.', ''),
(547, 53, 6, 'Add pandan flavoring and mix well.', ''),
(548, 53, 7, 'Add young coconut strips, nata de coco, and kaong.', ''),
(549, 53, 8, 'Add the gulaman cubes.', ''),
(550, 53, 9, 'Mix gently until evenly combined.', ''),
(551, 53, 10, 'Refrigerate for at least 3 hours.', ''),
(552, 53, 11, 'Serve chilled.', ''),
(553, 54, 1, 'Combine chilled all-purpose cream and condensed milk in a bowl.', ''),
(554, 54, 2, 'Mix until smooth and creamy.', ''),
(555, 54, 3, 'Arrange a layer of graham crackers in a rectangular dish.', ''),
(556, 54, 4, 'Spread a layer of cream mixture over the crackers.', ''),
(557, 54, 5, 'Arrange sliced mangoes on top.', ''),
(558, 54, 6, 'Repeat the layers until all ingredients are used.', ''),
(559, 54, 7, 'Finish with cream mixture and crushed graham crackers.', ''),
(560, 54, 8, 'Cover the dish.', ''),
(561, 54, 9, 'Refrigerate for at least 6 hours or overnight.', ''),
(562, 54, 10, 'Slice and serve chilled.', ''),
(563, 55, 1, 'Combine gulaman powder, water, sugar, and instant coffee in a saucepan.', ''),
(564, 55, 2, 'Stir until the coffee and gulaman dissolve.', ''),
(565, 55, 3, 'Bring to a boil while stirring.', ''),
(566, 55, 4, 'Pour into a rectangular container.', ''),
(567, 55, 5, 'Allow to cool until firm.', ''),
(568, 55, 6, 'Cut the coffee jelly into small cubes.', ''),
(569, 55, 7, 'In a separate bowl, combine evaporated milk, condensed milk, all-purpose cream, and vanilla.', ''),
(570, 55, 8, 'Mix until smooth.', ''),
(571, 55, 9, 'Add the coffee jelly cubes.', ''),
(572, 55, 10, 'Stir gently.', ''),
(573, 55, 11, 'Refrigerate for at least 2 hours.', ''),
(574, 55, 12, 'Serve chilled.', ''),
(575, 56, 1, 'Drain the fruit cocktail, nata de coco, and kaong thoroughly.', ''),
(576, 56, 2, 'Place them in a large mixing bowl.', ''),
(577, 56, 3, 'Add young coconut strips.', ''),
(578, 56, 4, 'In another bowl, combine condensed milk and all-purpose cream.', ''),
(579, 56, 5, 'Mix until smooth.', ''),
(580, 56, 6, 'Pour the cream mixture over the fruits.', ''),
(581, 56, 7, 'Add cheese cubes if desired.', ''),
(582, 56, 8, 'Mix gently until all ingredients are coated.', ''),
(583, 56, 9, 'Cover and refrigerate for at least 4 hours.', ''),
(584, 56, 10, 'Serve chilled.', ''),
(585, 57, 1, 'Combine pork, soy sauce, and calamansi juice in a bowl.', ''),
(586, 57, 2, 'Marinate for 20–30 minutes in the refrigerator.', ''),
(587, 57, 3, 'Heat cooking oil in a pot.', ''),
(588, 57, 4, 'Sauté garlic and onion until fragrant.', ''),
(589, 57, 5, 'Add marinated pork and cook until lightly browned.', ''),
(590, 57, 6, 'Add tomato sauce, tomato paste, water, and bay leaves.', ''),
(591, 57, 7, 'Bring to a boil.', ''),
(592, 57, 8, 'Lower the heat and simmer for 30–40 minutes or until the pork is tender.', ''),
(593, 57, 9, 'Add potatoes and carrots.', ''),
(594, 57, 10, 'Cook for 10 minutes.', ''),
(595, 57, 11, 'Add pork liver and hotdogs.', ''),
(596, 57, 12, 'Simmer until the liver is fully cooked.', ''),
(597, 57, 13, 'Add bell pepper and green peas.', ''),
(598, 57, 14, 'Season with salt and black pepper.', ''),
(599, 57, 15, 'Simmer for another 3–5 minutes.', ''),
(600, 57, 16, 'Serve hot with steamed rice.', '');
